const body = $input.first().json.body;
const entry = body.entry?.[0]?.changes?.[0]?.value;
const msg = entry?.messages?.[0];
const contato = entry?.contacts?.[0];

const wa_id = msg?.from;
const nome = contato?.profile?.name || null;
const tipo_mensagem = msg?.type || 'unknown';
const msg_id = msg?.id || null;
const audio_media_id = msg?.audio?.id || null;
const texto = msg?.text?.body || '';

let origem = 'tiktok';
if (/\[ref:lp\]/i.test(texto)) origem = 'lp';
else if (/\[ref:tiktok\]/i.test(texto)) origem = 'tiktok';

return [{ json: { wa_id, nome, texto_recebido: texto, tipo_mensagem, audio_media_id, msg_id, origem } }];

const ctx = $node["Carregar contexto"].json;
const promptRows = ctx.prompts || [];
const produtos = ctx.produtos || [];
const lead = ctx.lead || {};
const extra = $node["Extrair mensagem e origem"].json;

// Texto ja consolidado pelo debounce: se ela mandou 3 mensagens seguidas,
// chega tudo junto aqui e o agente responde uma vez, considerando as tres.
const textoFinal = $node["Consumir buffer"].json;

const objetivo   = promptRows.find(r => r.chave === 'objetivo')?.conteudo || '';
const compliance = promptRows.find(r => r.chave === 'compliance')?.conteudo || '';
const objecoes   = promptRows.find(r => r.chave === 'objecoes')?.conteudo || '';

// vem em ordem decrescente da funcao; inverte para cronologica
const historico = (ctx.historico || []).slice().reverse();

// ---------------------------------------------------------------------------
// OBJECOES SOB DEMANDA
// objecoes.md tem 5.129 tokens em 17 secoes (A-Q). Uma conversa levanta 2 ou 3.
// Carregar tudo em toda mensagem custa ~3.500 tokens desperdicados por turno.
// Aqui o texto e fatiado pelos cabecalhos "## " e so entram: o nucleo (sempre)
// + as secoes cujo gatilho aparece na mensagem atual ou nas 4 ultimas trocas.
// Selecao por palavra-chave: custo zero, sem chamada extra de modelo.
// ---------------------------------------------------------------------------
function fatiar(txt) {
  const out = {};
  for (const bloco of txt.split(/\n(?=## )/)) {
    const titulo = (bloco.split('\n')[0] || '').replace(/^##\s*/, '').trim();
    out[titulo] = bloco;
  }
  return out;
}

// Sempre presentes: base factual, voz, guardrail de sofrimento e fechamento.
// "P." nunca sai — e o unico caminho que faz o agente parar de vender.
const SEMPRE = [/^FATOS OPERACIONAIS/, /^Voz e abertura/, /^P\./, /^Como isso conecta/];

// Gatilhos por secao. Sem acento nos padroes; o texto e normalizado antes.
const GATILHOS = [
  [/^A\./, /(nao e pra mim|nao preciso|ja tenho minha forma|minha fe|nao sou de)/],
  [/^B\./, /(igreja|missa|paroquia|padre da minha|substitui)/],
  [/^C\./, /(funciona|ajuda mesmo|confiar|e serio|golpe|verdade|resolve)/],
  [/^D\./, /(generico|superficial|raso|qualquer um|profundidade)/],
  [/^E\./, /(tempo|corrid|ocupad|constancia|nao vou usar|esquec)/],
  [/^F\./, /(comunidade|grupo|ativ[ao]|exposi|exposta|privacidade|whatsapp|telegram)/],
  [/^G\./, /(audio|ouvir|escutar|youtube|de graca|gratis|spotify)/],
  [/^H\./, /(preco|caro|custa|valor|dinheiro|pagar|barato|cobrar|reais|r\$)/],
  [/^I\./, /(padre|frei|responde|direto|falar com ele|marketing)/],
  [/^J\./, /(confiavel|quem esta por tras|quem faz|serio mesmo|espiritualmente|seita)/],
  [/^K\./, /(o que e|o que vem|como funciona|o que recebo|oq e|conteudo|inclui)/],
  [/^L\./, /(como recebo|entrega|acesso|chega|fisico|digital|onde|depois de pagar|email)/],
  [/^M\./, /(garantia|reembolso|dinheiro de volta|arrepend|cancelar|devolv|7 dias)/],
  [/^N\./, /(marido|esposo|filh|pastor|falar com|decidir sozinha|conversar com)/],
  [/^O\./, /(figurinha|sticker|foto|imagem|video)/],
  [/^Q\./, /(spam|para de|sai daqui|quem e voce|robo|bot)/],
];

function normalizar(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function montarObjecoes(txt) {
  if (!txt) return { nucleo: '', sobDemanda: '' };
  const secoes = fatiar(txt);
  const titulos = Object.keys(secoes);

  const nucleo = titulos.filter(t => SEMPRE.some(r => r.test(t)))
                        .map(t => secoes[t]).join('\n\n');

  // Janela de deteccao: mensagem atual + ultimas 4 trocas. Uma objecao levantada
  // ha 3 mensagens ainda esta viva na conversa; so a mensagem atual perde o fio.
  const janela = normalizar(
    textoFinal + ' ' +
    historico.slice(-4).map(h => (h.mensagem_lead || '')).join(' ')
  );

  const escolhidas = titulos.filter(t =>
    !SEMPRE.some(r => r.test(t)) &&
    GATILHOS.some(([alvo, gatilho]) => alvo.test(t) && gatilho.test(janela))
  );

  return { nucleo, sobDemanda: escolhidas.map(t => secoes[t]).join('\n\n') };
}

const obj = montarObjecoes(objecoes);

// Tabela de desconto REAL, com a MESMA formula usada em "Montar items do carrinho".
function calcularTotal(itens) {
  const fator = 1 - (Math.max(0, itens.length - 1) * 10) / 100;
  return itens.reduce((soma, p) => soma + Math.round(p.preco_centavos * fator), 0);
}
function fmt(centavos) { return (centavos / 100).toFixed(2).replace('.', ','); }

// #11 O agente precisa saber o que ela JA TEM, senao tenta vender de novo.
const jaComprados = new Set((lead.produtos_comprados || []).map(i => i.produto_id || i.title));
const disponiveis = produtos.filter(p => !jaComprados.has(p.produto_id) && !jaComprados.has(p.nome));

// Montado a partir de `disponiveis`, nao de `produtos`: o prompt afirma que os
// ja comprados foram excluidos, entao a lista precisa refletir isso de fato.
const catalogoTexto = disponiveis.map(p => {
  let linha = '- ' + p.produto_id + ' (' + p.tipo + '): ' + p.nome + ' - R$ ' + (p.preco_centavos/100).toFixed(2);
  if (p.resolve_objecao && p.resolve_objecao.length) linha += ' [resolve objecao: ' + p.resolve_objecao.join(', ') + ']';
  if (p.arquetipos && p.arquetipos.length) linha += ' [arquetipo: ' + p.arquetipos.join(', ') + ']';
  return linha;
}).join('\n');

const principal = disponiveis.find(p => p.tipo === 'principal');
const bumps = disponiveis.filter(p => p.tipo === 'order_bump').sort((a, b) => a.ordem - b.ordem);

let tabelaDesconto = '';
if (principal && bumps.length) {
  let acumulado = [principal];
  const linhas = [];
  for (const bump of bumps) {
    const semDesconto = acumulado.reduce((s, p) => s + p.preco_centavos, 0) + bump.preco_centavos;
    acumulado = [...acumulado, bump];
    const comDesconto = calcularTotal(acumulado);
    const descontoPct = Math.max(0, acumulado.length - 1) * 10;
    linhas.push('*+ ' + bump.nome + '* (R$ ' + fmt(bump.preco_centavos) + ')\n   Total: R$ ' + fmt(comDesconto) + ' - voce economiza *R$ ' + fmt(semDesconto - comDesconto) + '* (' + descontoPct + '% OFF)');
  }
  tabelaDesconto = '*Sua ' + principal.nome + ' - R$ ' + fmt(principal.preco_centavos) + '*\n\nVeja como o valor final cai conforme voce completa sua protecao:\n\n' + linhas.join('\n\n') + '\n\nEscolha quantos quiser -- quanto mais completa, maior o desconto';
}

// ===========================================================================
// BLOCO A -- ESTATICO. Identico em toda chamada, para toda lead, para sempre.
// A OpenAI faz cache automatico do maior prefixo comum (>=1024 tokens) e cobra
// 25% nele. Por isso TUDO que nao varia vem aqui, antes de qualquer dado de
// lead: cada instrucao que escorrega para o Bloco B passa a custar preco cheio
// em todas as ~20 mensagens da conversa.
// NAO INSIRA NADA VARIAVEL AQUI -- uma unica interpolacao por lead (nome, data,
// preco, status) quebra o cache do prompt inteiro e o custo triplica.
// ===========================================================================
const BLOCO_A = [
  objetivo,
  compliance,
  obj.nucleo ? 'GUIA DE OBJECOES -- NUCLEO (sempre ativo, dentro do compliance acima):\n' + obj.nucleo : '',

  'PIVO POR OBJECAO: se o lead recusar o principal ou repetir uma objecao forte (ex: "esta caro", "nao tenho interesse", "vou pensar") DEPOIS de voce ja ter tentado tratar a objecao uma vez, ofereca o produto do catalogo cuja tag [resolve objecao] bate com o sinal. Nao insista mais de uma vez na mesma linha de recusa.',

  'ARQUETIPO: identifique ao longo da conversa qual arquetipo da lead mais se encaixa (mae_protetora: fala de filhos/familia/protecao; guerreira_fe: fala de batalha/forca/nao desistir; devota_busca: fala de milagre/graca/resposta/sinal; mulher_pertence: fala de comunidade/nao estar sozinha). Priorize o produto cujo [arquetipo] bate com o perfil. Sem sinal claro, retorne null -- nunca invente arquetipo sem evidencia.',

  'DESCONTO DE RECUPERACAO: ao oferecer o produto alternativo do pivo, voce pode liberar 20% para ela fechar agora. Diga algo como "consigo liberar 20% pra voce fechar agora" -- NUNCA diga que e "so hoje", "ultima chance" ou qualquer coisa datada. E concessao real e sempre disponivel. Nesse caso defina pivo_downsell=true; em qualquer outro gerar_link, false.',

  'DADOS DE PAGAMENTO: o BlackCat exige email e CPF no proprio pedido -- o link so e gerado com os dois. Assim que ela aceitar o stack, peca ambos numa unica mensagem objetiva. So retorne intent="gerar_link" quando tiver os dois; enquanto faltar, use intent="aceitou_stack" pedindo so o que falta. Retorne SEMPRE os campos email e cpf com o valor mais recente informado, ou null. Nunca invente nem deduza.',

  'SINAL DE SOFRIMENTO REAL (secao P do nucleo): se a lead demonstrar angustia genuina -- perda, doenca grave, desesperanca, qualquer mencao a se ferir -- isso sobrepoe qualquer objetivo de venda. Pare de vender, acolha, nao ofereca produto, e retorne intent="sofrimento". Havendo risco a vida, oriente ajuda imediata (CVV 188).',

  'PEDIDO DE PARAR: se ela pedir para nao receber mais mensagens ("nao me manda mais", "para", "sai", "me tira daqui"), retorne intent="opt_out" e uma unica mensagem curta de despedida respeitosa, sem tentar reverter e sem perguntar o motivo. Respeitar isso na hora e obrigacao legal.',

  // #9 uma parede de texto nao se le no celular, ainda menos neste publico
  'FORMATO DA RESPOSTA: responda como uma pessoa digitando no WhatsApp -- de 1 a 3 mensagens curtas, na ordem em que seriam enviadas, cada uma com 1 a 3 linhas. Quebre pensamentos diferentes em mensagens diferentes em vez de mandar um bloco unico. A tabela de precos, quando usada, vai numa mensagem propria e inteira (nunca partida no meio).',

  'Responda SEMPRE em JSON: {"mensagens": string[], "intent": "qualificando"|"objecao"|"aceitou_stack"|"gerar_link"|"recusou"|"sofrimento"|"opt_out", "produtos_aceitos": string[], "arquetipo": "mae_protetora"|"guerreira_fe"|"devota_busca"|"mulher_pertence"|null, "pivo_downsell": boolean, "email": string|null, "cpf": string|null}',
].filter(Boolean).join('\n\n');

// ===========================================================================
// BLOCO B -- VARIAVEL. So o que muda por lead ou por mensagem.
// ===========================================================================
const partesB = [];

if (obj.sobDemanda) {
  partesB.push('GUIA DE OBJECOES -- SECOES RELEVANTES A ESTA CONVERSA:\n' + obj.sobDemanda);
}

partesB.push('Origem do lead nesta conversa: ' + extra.origem + '.');

// #3 Estado da lead manda em tudo que vem depois.
if (lead.status === 'aguardando_humano') {
  partesB.push('*** MODO SEM VENDA (prioridade maxima) ***\nEsta lead foi sinalizada por sofrimento real e esta aguardando atendimento humano. NAO ofereca produto, NAO cite preco, NAO tente retomar a venda em nenhuma hipotese, mesmo que ela pergunte sobre produto. Acolha com humanidade, diga que uma pessoa de verdade vai falar com ela, e se houver risco a vida oriente ajuda imediata (CVV 188). Retorne intent="sofrimento".');
}

if (jaComprados.size) {
  partesB.push('PRODUTOS QUE ESTA LEAD JA COMPROU (nunca ofereca de novo, nunca inclua em produtos_aceitos): '
    + [...jaComprados].join(', ') + '. Se ela perguntar sobre um deles, trate como cliente: ajude com acesso e uso, nao venda.');
}

partesB.push('Catalogo disponivel para ESTA lead (ja excluidos os que ela possui; use exatamente estes produto_id, nunca invente produto ou preco fora desta lista):\n' + (catalogoTexto || '(nenhum produto novo a oferecer)'));

if (tabelaDesconto) {
  partesB.push('Quando o lead aceitar o produto principal, apresente TODOS os order_bump de uma vez (nao um a um). Use EXATAMENTE estes valores (ja calculados, batem com o que sera cobrado -- nunca invente ou recalcule):\n\n' + tabelaDesconto
    + '\n\nVoce pode ajustar saudacao/tom ao redor, mas NUNCA altere os valores em R$ ou os percentuais.');
}

// #13 link ainda valido: reenviar em vez de criar outra cobranca
if (lead.link_recente && lead.ultimo_link_url) {
  partesB.push('JA EXISTE UM LINK DE PAGAMENTO ABERTO para esta lead, gerado ha menos de 30 minutos: ' + lead.ultimo_link_url
    + '\nSe ela pedir o link de novo, disser que perdeu ou que nao chegou, REENVIE ESTE MESMO LINK no texto da sua resposta e retorne intent="qualificando". NAO retorne gerar_link -- criar outra cobranca deixaria duas em aberto no nome dela.');
}

partesB.push('DADOS JA CONHECIDOS DESTE LEAD: email=' + (lead.email || 'nao informado') + ', cpf=' + (lead.cpf || 'nao informado') + '. Se algum ja constar, trate como JA INFORMADO: nao peca de novo, reutilize e devolva no campo correspondente.');

const systemPrompt = BLOCO_A + '\n\n' + partesB.join('\n\n');

// ---------------------------------------------------------------------------
// CAP DE HISTORICO
// O historico inteiro era reenviado a cada turno e crescia sem limite. Mantem
// as ultimas MAX_TROCAS na integra (onde esta o fio da conversa) e resume o que
// veio antes numa linha, para nao perder o que a lead ja disse.
// ---------------------------------------------------------------------------
const MAX_TROCAS = 8;
const messages = [{ role: 'system', content: systemPrompt }];

const antigas = historico.slice(0, Math.max(0, historico.length - MAX_TROCAS));
const recentes = historico.slice(-MAX_TROCAS);

if (antigas.length) {
  const resumo = antigas.map(h => (h.mensagem_lead || '').trim()).filter(Boolean).join(' | ').slice(0, 600);
  messages.push({
    role: 'system',
    content: 'RESUMO DO INICIO DA CONVERSA (' + antigas.length + ' trocas anteriores, o que a lead disse): ' + resumo
  });
}

for (const h of recentes) {
  if (h.mensagem_lead) messages.push({ role: 'user', content: h.mensagem_lead });
  if (h.mensagem_agente) messages.push({ role: 'assistant', content: h.mensagem_agente });
}
messages.push({ role: 'user', content: textoFinal });

return [{ json: { model: 'gpt-4.1', response_format: { type: 'json_object' }, messages } }];

const parsed = JSON.parse($input.first().json.choices[0].message.content);

// Tolerante ao modelo devolver 'resposta' (string) em vez de 'mensagens' (array).
let mensagens = parsed.mensagens;
if (!Array.isArray(mensagens) || !mensagens.length) {
  mensagens = parsed.resposta ? [parsed.resposta] : [];
}
mensagens = mensagens.map(m => String(m).trim()).filter(Boolean);

// Nunca deixar a lead sem resposta por formato inesperado.
if (!mensagens.length) mensagens = ['Me conta um pouco mais pra eu te ajudar direito.'];

return [{ json: { ...parsed, mensagens, resposta: mensagens.join('\n\n') } }];

const idsAceitos = $node["Extrair resposta e intent"].json.produtos_aceitos || [];
const pivoDownsell = $node["Extrair resposta e intent"].json.pivo_downsell === true;
const catalogo = $node["Carregar contexto"].json.produtos || [];

const selecionados = idsAceitos.map(id => catalogo.find(p => p.produto_id === id)).filter(Boolean);

let descontoPct;
if (pivoDownsell) {
  // Desconto FIXO de recuperacao para o pivo por objecao (catalogo-produtos.md, secao 3).
  // E uma concessao real, sempre disponivel -- nunca rotulada como "so hoje" ou datada
  // (compliance-e-etica.md, secao 2). Constante intencional, nao depende do tamanho do carrinho.
  descontoPct = 20;
} else {
  // Desconto por tamanho do stack (principal + order bumps), 10% por item adicional.
  descontoPct = Math.max(0, selecionados.length - 1) * 10;
}
const fator = 1 - (descontoPct / 100);

const items = selecionados.map(p => ({
  title: p.nome,
  quantity: 1,
  unitPrice: Math.round(p.preco_centavos * fator)
}));
const amount = items.reduce((soma, item) => soma + item.unitPrice * item.quantity, 0);

return [{ json: { items, amount, descontoPct } }];

const base = $node["Extrair mensagem e origem"].json;
let transcricao = "";
try { transcricao = ($input.first().json.text || "").trim(); } catch (e) { transcricao = ""; }
// Transcricao vazia = audio nao compreendido. Nao inventa fala: devolve vazio e deixa
// o IF "Tem texto para responder?" acionar a resposta honesta da secao O do objecoes.md.
return [{ json: { ...base, texto_recebido: transcricao } }];

const item = $input.first();
if (!item.binary || !item.binary.data) {
  // Download falhou (o node anterior segue em erro de proposito): devolve sem binario
  // para o Whisper falhar rapido e o fluxo cair no caminho de 'nao consegui ler'.
  return [{ json: {} }];
}
item.binary.data.fileName = 'audio.ogg';
item.binary.data.mimeType = item.binary.data.mimeType || 'audio/ogg';
return [item];

const wa = $node["Extrair mensagem e origem"].json.wa_id;
// Um item por mensagem: o sub-workflow envia em sequencia, com pausa entre elas.
return $node["Extrair resposta e intent"].json.mensagens.map(texto => ({ json: { to: wa, tipo: 'text', texto } }));

const e = $node["Extrair mensagem e origem"].json;
const texto = $node["Consumir buffer"].json;
return [{ json: { to: '<<RODRIGO_WA_NUMBER>>', tipo: 'text', texto: '⚠️ Sinal de sofrimento real detectado.
Lead: ' + (e.nome || e.wa_id) + ' (' + e.wa_id + ')
Mensagem: "' + texto + '"
O agente ja parou de vender e acolheu. Preciso que voce (ou alguem de confianca) assuma esta conversa agora.' } }];

const wa = $node["Extrair mensagem e origem"].json.wa_id;
return [
  { json: { to: wa, tipo: 'text', texto: 'Deu um probleminha aqui do meu lado agora. Ja ja te respondo, ta bom? Nao vou te deixar sem resposta.' } },
  { json: { to: '<<RODRIGO_WA_NUMBER>>', tipo: 'text', texto: '\u26a0\ufe0f OpenAI falhou para o lead ' + wa + '. Ela foi avisada e esta esperando. Verifique credito/limite da conta.' } }
];

const wa = $node["Extrair mensagem e origem"].json.wa_id;
return [
  { json: { to: wa, tipo: 'text', texto: 'Nao consegui gerar seu link agora, foi um problema tecnico aqui. Ja estou resolvendo e te mando em seguida.' } },
  { json: { to: '<<RODRIGO_WA_NUMBER>>', tipo: 'text', texto: '\u26a0\ufe0f BlackCat recusou o create-sale do lead ' + wa + '. Ela pediu o link e esta esperando.' } }
];
